example:
static int Pack(int bags)
{
    if (bags < 0)
    {
        throw new ArgumentException("bags cannot be negative");
    }

    return bags * 2;
}

static int SafePack(int bags)
{
    try
    {
        return Pack(bags);
    }
    catch (ArgumentException)
    {
        return -1;
    }
}
